1|// Single swap point for the music-mode control (style stickers plus the
2|// Chopin button). The player renders <MusicStyleControl /> and must not
3|// know its internals: replacing this file and
4|// app/styles/music-style-control.css swaps the whole design.
5|import { useRef } from "react";
6|import type { MusicMode, MusicModeId } from "@/core/music";
7|
8|export type MusicStyleControlProps = {
9|  modes: MusicMode[];
10|  current: MusicModeId | null;
11|  onAdvance: (to?: MusicModeId) => void;
12|};
13|
14|function stickerFor(id: string, label: string): string {
15|  return /piano/i.test(id) || /piano/i.test(label)
16|    ? "/art/stickers/piano.svg"
17|    : "/art/stickers/violin.svg";
18|}
19|
20|export function MusicStyleControl({ modes, current, onAdvance }: MusicStyleControlProps) {
21|  const styles = modes.filter((m) => m.kind === "style");
22|  const playlist = modes.find((m) => m.kind === "playlist") ?? null;
23|  // The last picked style, so the Chopin button pressed while on Chopin
24|  // returns to it instead of cycling forward.
25|  const lastStyle = useRef<MusicModeId | null>(null);
26|  if (current !== null && styles.some((s) => s.id === current)) lastStyle.current = current;
27|  return (
28|    <>
29|      {styles.length >= 2 ? (
30|        <span className="stickers" role="group" aria-label="Music style">
31|          {styles.map((s) => (
32|            <span className="sticker-wrap" key={s.id}>
33|              <button
34|                type="button"
35|                className="sticker"
36|                onClick={() => onAdvance(s.id)}
37|                aria-pressed={current === s.id}
38|                aria-label={s.label}
39|                title={s.label}
40|              >
41|                <img src={stickerFor(s.id, s.label)} alt="" width={40} height={40} />
42|              </button>
43|              <span className="sticker-dot" aria-hidden="true" />
44|            </span>
45|          ))}
46|        </span>
47|      ) : null}
48|      {playlist !== null ? (
49|        <button
50|          type="button"
51|          className="chopin"
52|          onClick={() =>
53|            current === playlist.id
54|              ? onAdvance(lastStyle.current ?? styles[0]?.id)
55|              : onAdvance(playlist.id)
56|          }
57|          aria-pressed={current === playlist.id}
58|          aria-label="Just play Chopin"
59|          title="Just play Chopin"
60|        >
61|          <img
62|            src="/art/chopin-just-play-me.png"
63|            alt="Just play Chopin"
64|            width={40}
65|            height={40}
66|          />
67|        </button>
68|      ) : null}
69|    </>
70|  );
