1|// Music session: the single policy owner behind the reader. Pure and
2|// React-free: no timers, no Date.now, no Math.random, no storage. The
3|// reader builds the context (clock, rng, scene signals) and bridges the
4|// view to React state. The player stays the mechanism that performs
5|// crossfades; this module decides them.
6|import { MUSIC_CONFIG, nextTrack, resolveInitialSelection } from "./music";
7|import type {
8|  MusicManifest,
9|  MusicSelection,
10|  PersistedMusicPrefs,
11|  Rng,
12|  SceneSignal,
13|} from "./music";
14|import {
15|  enterPlaylist,
16|  exitPlaylist,
17|  initScheduler,
18|  noteTrackEnded,
19|  observeScene,
20|  requestManualTrack,
21|  requestNext,
22|  switchStyle,
23|  tickScheduler,
24|} from "./music-schedule";
25|import type { ScheduleDecision, SchedulerState } from "./music-schedule";
26|import { currentMode, findChopinPlaylist, musicModes, nextMode } from "./music-modes";
27|import type { MusicModeId } from "./music-modes";
28|export { findChopinPlaylist } from "./music-modes";
29|import { popHistory, pushHistory } from "./music-history";
30|
31|export interface MusicSession {
32|  scheduler: SchedulerState;
33|  history: string[];
34|  selection: MusicSelection;
35|  fadeSec: number;
36|  replayNonce: number;
37|  view: SessionView;
38|}
39|
40|export interface SessionView {
41|  currentId: string | null;
42|  fadeSec: number;
43|  replayNonce: number;
44|  canPrev: boolean;
45|  canSkip: boolean;
46|  playlistOn: boolean;
47|  style: string | null;
48|}
49|
50|export interface SessionContext {
51|  manifest: MusicManifest;
52|  signalOf: (sceneId: string) => SceneSignal | null;
53|  routeSceneId: string | null;
54|  nowSec: number;
55|  rng: Rng;
56|}
57|
58|export type MusicIntent =
59|  | { type: "sceneEntered"; sceneId: string }
60|  | { type: "tick" }
61|  | { type: "skip" }
62|  | { type: "previous" }
63|  | { type: "styleChanged"; style: string }
64|  | { type: "trackEnded"; trackId: string }
65|  | { type: "playlistToggled" }
66|  | { type: "modeAdvanced"; to?: MusicModeId };
67|
68|// Route entries use the short dwell; the draw and the holds are unchanged.
69|const ENTRY_DWELL = { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
70|
71|export function startSession(
72|  manifest: MusicManifest,
73|  prefs: PersistedMusicPrefs | null,
74|): MusicSession {
75|  const fields = {
76|    scheduler: initScheduler(),
77|    history: [] as string[],
78|    selection: resolveInitialSelection(manifest, prefs),
79|    fadeSec: 0,
80|    replayNonce: 0,
81|  };
82|  // A stored Chopin mode starts in the playlist at once (fade 0, like the
83|  // first scene entry); without the playlist the stored style stands.
84|  if (prefs?.playlist === true) {
85|    const playlist = findChopinPlaylist(manifest);
86|    if (playlist) {
87|      const decision = enterPlaylist(fields.scheduler, manifest, playlist.id, 0);
88|      const entered = foldSwitch(fields, decision, false);
89|      return { ...entered, view: buildView(entered, manifest, null, entered.selection) };
90|    }
91|  }
92|  return {
93|    ...fields,
94|    view: buildView(fields, manifest, null, fields.selection),
95|  };
96|}
97|
98|function sameScheduler(a: SchedulerState, b: SchedulerState): boolean {
99|  return (
100|    a.currentId === b.currentId &&
101|    a.currentStartedSec === b.currentStartedSec &&
102|    a.activeSceneId === b.activeSceneId &&
103|    a.pendingSceneId === b.pendingSceneId &&
104|    a.pendingSinceSec === b.pendingSinceSec &&
105|    a.overrideId === b.overrideId &&
106|    a.overrideSceneId === b.overrideSceneId &&
107|    (a.playlist === null || b.playlist === null
108|      ? a.playlist === b.playlist
109|      : a.playlist.id === b.playlist.id && a.playlist.index === b.playlist.index)
110|  );
111|}
112|
113|function viewEqual(a: SessionView, b: SessionView): boolean {
114|  return (
115|    a.currentId === b.currentId &&
116|    a.fadeSec === b.fadeSec &&
117|    a.replayNonce === b.replayNonce &&
118|    a.canPrev === b.canPrev &&
119|    a.canSkip === b.canSkip &&
120|    a.playlistOn === b.playlistOn &&
121|    a.style === b.style
122|  );
123|}
124|
125|function buildView(
126|  fields: Omit<MusicSession, "view">,
127|  manifest: MusicManifest,
128|  routeSignal: SceneSignal | null,
129|  selection: MusicSelection,
130|): SessionView {
131|  const currentId = fields.scheduler.currentId;
132|  const playlistOn = fields.scheduler.playlist !== null;
133|  const canSkip = playlistOn
134|    ? (findChopinPlaylist(manifest)?.trackIds.length ?? 0) > 1
135|    : manifest.tracks.length > 1 &&
136|      nextTrack(routeSignal, manifest, currentId, undefined, selection) !== null;
137|  return {
138|    currentId,
139|    fadeSec: fields.fadeSec,
140|    replayNonce: fields.replayNonce,
141|    canPrev: currentId !== null,
142|    canSkip,
143|    playlistOn,
144|    style: selection.style,
145|  };
146|}
147|
148|function routeSignalOf(ctx: SessionContext): SceneSignal | null {
149|  return ctx.routeSceneId !== null ? ctx.signalOf(ctx.routeSceneId) : null;
150|}
151|
152|// Rebuild the session after a handler ran, reusing the session and the
153|// view objects when nothing changed so the reader's 1 s tick rerenders
154|// nothing.
155|function settle(session: MusicSession, fields: Omit<MusicSession, "view">, ctx: SessionContext): MusicSession {
156|  const view = buildView(fields, ctx.manifest, routeSignalOf(ctx), fields.selection);
157|  if (
158|    sameScheduler(session.scheduler, fields.scheduler) &&
159|    session.history === fields.history &&
160|    session.selection === fields.selection &&
161|    session.fadeSec === fields.fadeSec &&
162|    session.replayNonce === fields.replayNonce &&
163|    viewEqual(session.view, view)
164|  ) {
165|    return session;
166|  }
167|  return { ...fields, view: viewEqual(session.view, view) ? session.view : view };
168|}
169|
170|// Fold a scheduler decision into the session: fade on every switch, a
171|// replay nonce bump on a same-id wrap, and the outgoing id banked for
172|// Previous on every automatic switch. Previous passes push false so it
173|// never re-banks.
174|function foldSwitch(
175|  base: Omit<MusicSession, "view">,
176|  decision: ScheduleDecision,
177|  push: boolean,
178|): Omit<MusicSession, "view"> {
179|  const prevId = base.scheduler.currentId;
180|  if (decision.switchToId === null) return { ...base, scheduler: decision.state };
181|  if (decision.switchToId === prevId) {
182|    return {
183|      ...base,
184|      scheduler: decision.state,
185|      fadeSec: decision.crossfadeSec,
186|      replayNonce: base.replayNonce + 1,
187|    };
188|  }
189|  return {
190|    ...base,
191|    scheduler: decision.state,
192|    history: push && prevId !== null ? pushHistory(base.history, prevId) : base.history,
193|    fadeSec: decision.crossfadeSec,
194|  };
195|}
196|
197|function baseOf(session: MusicSession): Omit<MusicSession, "view"> {
198|  return {
199|    scheduler: session.scheduler,
200|    history: session.history,
201|    selection: session.selection,
202|    fadeSec: session.fadeSec,
203|    replayNonce: session.replayNonce,
204|  };
205|}
206|
207|function selectEnv(session: MusicSession, ctx: SessionContext) {
208|  return { selection: session.selection, rng: ctx.rng };
209|}
210|
211|export function dispatch(session: MusicSession, intent: MusicIntent, ctx: SessionContext): MusicSession {
212|  switch (intent.type) {
213|    case "sceneEntered": {
214|      const signal = ctx.signalOf(intent.sceneId);
215|      const decision = observeScene(
216|        session.scheduler,
217|        intent.sceneId,
218|        signal,
219|        ctx.manifest,
220|        ctx.nowSec,
221|        selectEnv(session, ctx),
222|        ENTRY_DWELL,
223|      );
224|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
225|    }
226|    case "tick": {
227|      if (ctx.routeSceneId === null) return session;
228|      const sceneId = session.scheduler.pendingSceneId ?? ctx.routeSceneId;
229|      const decision = tickScheduler(
230|        session.scheduler,
231|        ctx.signalOf(sceneId),
232|        ctx.manifest,
233|        ctx.nowSec,
234|        selectEnv(session, ctx),
235|        ENTRY_DWELL,
236|      );
237|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
238|    }
239|    case "skip": {
240|      if (ctx.routeSceneId === null) return session;
241|      const decision = requestNext(
242|        session.scheduler,
243|        ctx.signalOf(ctx.routeSceneId),
244|        ctx.manifest,
245|        ctx.nowSec,
246|        selectEnv(session, ctx),
247|      );
248|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
249|    }
250|    case "previous": {
251|      if (session.scheduler.playlist !== null) {
252|        return settle(session, { ...baseOf(session), replayNonce: session.replayNonce + 1 }, ctx);
253|      }
254|      const popped = popHistory(session.history);
255|      if (!popped) {
256|        return settle(session, { ...baseOf(session), replayNonce: session.replayNonce + 1 }, ctx);
257|      }
258|      const base = { ...baseOf(session), history: popped.hist };
259|      // Audible scope, not style scope: Previous may return to a track
260|      // from before a style change, as it always could.
261|      const decision = requestManualTrack(session.scheduler, ctx.manifest, popped.id, ctx.nowSec);
262|      return settle(session, foldSwitch(base, decision, false), ctx);
263|    }
264|    case "styleChanged": {
265|      if (ctx.routeSceneId === null) return session;
266|      if (session.scheduler.playlist !== null) return session;
267|      if (intent.style === session.selection.style) return session;
268|      const decision = switchStyle(
269|        session.scheduler,
270|        ctx.signalOf(ctx.routeSceneId),
271|        ctx.manifest,
272|        ctx.nowSec,
273|        intent.style,
274|      );
275|      if (decision.switchToId === null) return session;
276|      const fields = foldSwitch(baseOf(session), decision, true);
277|      return settle(session, { ...fields, selection: { style: intent.style } }, ctx);
278|    }
279|    case "trackEnded": {
280|      if (ctx.routeSceneId === null) return session;
281|      const decision = noteTrackEnded(
282|        session.scheduler,
283|        ctx.signalOf(ctx.routeSceneId),
284|        ctx.manifest,
285|        intent.trackId,
286|        ctx.nowSec,
287|        selectEnv(session, ctx),
288|      );
289|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
290|    }
291|    case "playlistToggled": {
292|      const playlist = findChopinPlaylist(ctx.manifest);
293|      if (!playlist) return session;
294|      if (session.scheduler.playlist !== null) {
295|        const signal = ctx.routeSceneId !== null ? ctx.signalOf(ctx.routeSceneId) : null;
296|        const decision = exitPlaylist(
297|          session.scheduler,
298|          signal,
299|          ctx.manifest,
300|          ctx.nowSec,
301|          selectEnv(session, ctx),
302|        );
303|        return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
304|      }
305|      const decision = enterPlaylist(session.scheduler, ctx.manifest, playlist.id, ctx.nowSec);
306|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
307|    }
308|    case "modeAdvanced": {
309|      const modes = musicModes(ctx.manifest);
310|      const target = intent.to ?? nextMode(modes, currentMode(session.view));
311|      if (target === null || !modes.some((m) => m.id === target)) return session;
312|      if (target === currentMode(session.view)) return session;
313|      const playlist = findChopinPlaylist(ctx.manifest);
314|      if (playlist !== null && target === playlist.id) {
315|        if (session.scheduler.playlist !== null) return session;
316|        const decision = enterPlaylist(session.scheduler, ctx.manifest, playlist.id, ctx.nowSec);
317|        return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
318|      }
319|      const signal = ctx.routeSceneId !== null ? ctx.signalOf(ctx.routeSceneId) : null;
320|      // Leaving the playlist switches straight to the target style: one
321|      // exit under the target selection, one switch, one crossfade.
322|      if (session.scheduler.playlist !== null) {
323|        const decision = exitPlaylist(session.scheduler, signal, ctx.manifest, ctx.nowSec, {
324|          selection: { style: target },
325|          rng: ctx.rng,
326|        });
327|        const fields = foldSwitch(baseOf(session), decision, true);
328|        return settle(session, { ...fields, selection: { style: target } }, ctx);
329|      }
330|      if (ctx.routeSceneId === null) return session;
331|      if (target === session.selection.style) return session;
332|      const decision = switchStyle(session.scheduler, signal, ctx.manifest, ctx.nowSec, target);
333|      if (decision.switchToId === null) return session;
334|      const fields = foldSwitch(baseOf(session), decision, true);
335|      return settle(session, { ...fields, selection: { style: target } }, ctx);
336|    }
337|    default: {
338|      const _exhaustive: never = intent;
339|      throw new Error(`unknown music intent: ${JSON.stringify(_exhaustive)}`);
340|    }
341|  }
342|}

