1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell and the min-track hold are testable without timers.
3|import {
4|  MUSIC_CONFIG,
5|  bestRanked,
6|  candidatesFor,
7|  nextTrack,
8|  requestStyleChange,
9|  resolveConfig,
10|  selectScheduled,
11|} from "./music";
12|import type {
13|  MusicConfig,
14|  MusicManifest,
15|  MusicSelection,
16|  SceneSignal,
17|  SelectEnv,
18|} from "./music";
19|
20|export interface SchedulerState {
21|  currentId: string | null;
22|  currentStartedSec: number;
23|  activeSceneId: string | null;
24|  pendingSceneId: string | null;
25|  pendingSinceSec: number;
26|  overrideId: string | null;
27|  overrideSceneId: string | null;
28|  playlist: { id: string; index: number } | null;
29|}
30|
31|export interface ScheduleDecision {
32|  state: SchedulerState;
33|  switchToId: string | null;
34|  crossfadeSec: number;
35|}
36|
37|export function initScheduler(): SchedulerState {
38|  return {
39|    currentId: null,
40|    currentStartedSec: 0,
41|    activeSceneId: null,
42|    pendingSceneId: null,
43|    pendingSinceSec: 0,
44|    overrideId: null,
45|    overrideSceneId: null,
46|    playlist: null,
47|  };
48|}
49|
50|function noChange(state: SchedulerState): ScheduleDecision {
51|  return { state, switchToId: null, crossfadeSec: 0 };
52|}
53|
54|// Scheduled select: the one draw from the selection module keeps the
55|// current track when it is eligible, so rescans do not churn. Dwell is
56|// handled by promotion; the draw itself holds the min-track pick.
57|function evaluateSwitch(
58|  state: SchedulerState,
59|  signal: SceneSignal | null,
60|  manifest: MusicManifest,
61|  nowSec: number,
62|  config: MusicConfig,
63|  env: SelectEnv,
64|): ScheduleDecision {
65|  if (signal === null) return noChange(state);
66|  if (state.playlist !== null) return noChange(state);
67|  const styleTracks = candidatesFor(env.selection, manifest);
68|  if (styleTracks.length === 0) return noChange(state);
69|  const pick = selectScheduled({
70|    cands: styleTracks,
71|    scene: signal,
72|    currentId: state.currentId,
73|    currentStartedSec: state.currentStartedSec,
74|    nowSec,
75|    rng: env.rng,
76|    override: config,
77|  });
78|  if (!pick || pick.id === state.currentId) return noChange(state);
79|  return {
80|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
81|    switchToId: pick.id,
82|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
83|  };
84|}
85|
86|function promote(
87|  state: SchedulerState,
88|  sceneId: string,
89|  signal: SceneSignal | null,
90|  manifest: MusicManifest,
91|  nowSec: number,
92|  config: MusicConfig,
93|  env: SelectEnv,
94|): ScheduleDecision {
95|  const settled: SchedulerState = {
96|    ...state,
97|    activeSceneId: sceneId,
98|    pendingSceneId: null,
99|    pendingSinceSec: 0,
100|    overrideId: null,
101|    overrideSceneId: null,
102|  };
103|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
104|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
105|}
106|
107|// The reading position entered a scene. It becomes pending and the dwell
108|// clock restarts, so fast scrolling keeps only the newest scene. After
109|// the pending scene holds for dwellSec it becomes active. The first
110|// track ever plays at once, with no dwell.
111|export function observeScene(
112|  state: SchedulerState,
113|  sceneId: string,
114|  signal: SceneSignal | null,
115|  manifest: MusicManifest,
116|  nowSec: number,
117|  env: SelectEnv,
118|  override?: Partial<MusicConfig>,
119|): ScheduleDecision {
120|  const config = resolveConfig(override ?? MUSIC_CONFIG);
121|  if (state.currentId === null) {
122|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
123|  }
124|  if (sceneId === state.activeSceneId) {
125|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
126|  }
127|  if (sceneId !== state.pendingSceneId) {
128|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
129|  }
130|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
131|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
132|}
133|
134|// Time passed: settle a pending scene whose dwell has expired, or
135|// re-check the active scene (a hold from minTrackSec may have expired).
136|// The reader passes the pending signal when one exists, else the active.
137|export function tickScheduler(
138|  state: SchedulerState,
139|  signal: SceneSignal | null,
140|  manifest: MusicManifest,
141|  nowSec: number,
142|  env: SelectEnv,
143|  override?: Partial<MusicConfig>,
144|): ScheduleDecision {
145|  const config = resolveConfig(override ?? MUSIC_CONFIG);
146|  if (state.currentId === null) return noChange(state);
147|  if (state.pendingSceneId !== null) {
148|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
149|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
150|  }
151|  // A skip override holds until the next scene change; promotion clears it.
152|  if (state.overrideId !== null) return noChange(state);
153|  if (state.activeSceneId === null) return noChange(state);
154|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
155|}
156|
157|// Reader skip: the same-emotion Next rule, applied at once with the
158|// normal crossfade. The choice holds until the next scene change.
159|export function requestNext(
160|  state: SchedulerState,
161|  signal: SceneSignal | null,
162|  manifest: MusicManifest,
163|  nowSec: number,
164|  env: SelectEnv,
165|  override?: Partial<MusicConfig>,
166|): ScheduleDecision {
167|  const config = resolveConfig(override ?? MUSIC_CONFIG);
168|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
169|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
170|  if (!next) return noChange(state);
171|  return {
172|    state: {
173|      ...state,
174|      currentId: next.id,
175|      currentStartedSec: nowSec,
176|      overrideId: next.id,
177|      overrideSceneId: state.activeSceneId,
178|    },
179|    switchToId: next.id,
180|    crossfadeSec: config.crossfadeSec,
181|  };
182|}
183|
184|// Manual pick from Previous: the track holds like a Next until the next
185|// scene change. Only tracks in the candidatesFor scope play, so a
186|// playlist-only id changes nothing. Unknown ids change nothing.
187|export function requestManualTrack(
188|  state: SchedulerState,
189|  manifest: MusicManifest,
190|  trackId: string,
191|  nowSec: number,
192|  selection?: MusicSelection | null,
193|  override?: Partial<MusicConfig>,
194|): ScheduleDecision {
195|  const config = resolveConfig(override ?? MUSIC_CONFIG);
196|  if (state.playlist !== null) return noChange(state);
197|  const scope = candidatesFor(selection ?? { style: null }, manifest);
198|  const picked = scope.find((t) => t.id === trackId) ?? null;
199|  if (!picked) return noChange(state);
200|  return {
201|    state: {
202|      ...state,
203|      currentId: picked.id,
204|      currentStartedSec: nowSec,
205|      overrideId: picked.id,
206|      overrideSceneId: state.activeSceneId,
207|    },
208|    switchToId: picked.id,
209|    crossfadeSec: config.crossfadeSec,
210|  };
211|}
212|
213|// A non-looping track ended: fade into the best remaining track,
214|// excluding the one that just ended. Never crosses styles.
215|export function noteTrackEnded(
216|  state: SchedulerState,
217|  signal: SceneSignal | null,
218|  manifest: MusicManifest,
219|  endedId: string,
220|  nowSec: number,
221|  env: SelectEnv,
222|  override?: Partial<MusicConfig>,
223|): ScheduleDecision {
224|  const config = resolveConfig(override ?? MUSIC_CONFIG);
225|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
226|  const styleTracks = candidatesFor(env.selection, manifest);
227|  if (styleTracks.length === 0) return noChange(state);
228|  const best = bestRanked(signal, styleTracks, endedId, config);
229|  if (!best) return noChange(state);
230|  return {
231|    state: {
232|      ...state,
233|      currentId: best.id,
234|      currentStartedSec: nowSec,
235|      overrideId: null,
236|      overrideSceneId: null,
237|    },
238|    switchToId: best.id,
239|    crossfadeSec: config.crossfadeSec,
240|  };
241|}
242|
243|// Fixed playlist mode (the Chopin easter egg). Playlist order lives here
244|// because it reuses SchedulerState and the crossfade config.
245|function playlistById(manifest: MusicManifest, id: string) {
246|  return manifest.playlists.find((p) => p.id === id) ?? null;
247|}
248|
249|// Enter playlist mode: switch at once to the first track, with no dwell
250|// and no min-track rule. Scene changes stay tracked but never switch.
251|export function enterPlaylist(
252|  state: SchedulerState,
253|  manifest: MusicManifest,
254|  playlistId: string,
255|  nowSec: number,
256|  override?: Partial<MusicConfig>,
257|): ScheduleDecision {
258|  const config = resolveConfig(override ?? MUSIC_CONFIG);
259|  const playlist = playlistById(manifest, playlistId);
260|  const firstId = playlist?.trackIds[0];
261|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
262|  if (!playlist || !first) return noChange(state);
263|  return {
264|    state: {
265|      ...state,
266|      currentId: first.id,
267|      currentStartedSec: nowSec,
268|      overrideId: null,
269|      overrideSceneId: null,
270|      playlist: { id: playlist.id, index: 0 },
271|    },
272|    switchToId: first.id,
273|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
274|  };
275|}
276|
277|// Next playlist track in trackIds order, wrapping last to first. Used by
278|// both the end-of-track path and the Next button while the playlist is on.
279|function advancePlaylist(
280|  state: SchedulerState,
281|  manifest: MusicManifest,
282|  nowSec: number,
283|  config: MusicConfig,
284|): ScheduleDecision {
285|  if (state.playlist === null) return noChange(state);
286|  const playlist = playlistById(manifest, state.playlist.id);
287|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
288|  // A one-track playlist wraps onto the same id. That still returns a
289|  // switch so the ended element re-cues instead of going quiet.
290|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
291|  const nextId = playlist.trackIds[nextIndex];
292|  if (nextId === undefined) return noChange(state);
293|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
294|  if (!next) return noChange(state);
295|  return {
296|    state: {
297|      ...state,
298|      currentId: next.id,
299|      currentStartedSec: nowSec,
300|      overrideId: null,
301|      overrideSceneId: null,
302|      playlist: { id: playlist.id, index: nextIndex },
303|    },
304|    switchToId: next.id,
305|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
306|  };
307|}
308|
309|// Leave playlist mode: clear the playlist state and switch at once to the
310|// best match for the current scene under the restored selection.
311|export function exitPlaylist(
312|  state: SchedulerState,
313|  signal: SceneSignal | null,
314|  manifest: MusicManifest,
315|  nowSec: number,
316|  env: SelectEnv,
317|  override?: Partial<MusicConfig>,
318|): ScheduleDecision {
319|  if (state.playlist === null) return noChange(state);
320|  const config = resolveConfig(override ?? MUSIC_CONFIG);
321|  const styleTracks = candidatesFor(env.selection, manifest);
322|  const cleared: SchedulerState = {
323|    ...state,
324|    overrideId: null,
325|    overrideSceneId: null,
326|    playlist: null,
327|  };
328|  const best = bestRanked(signal, styleTracks, null, config);
329|  if (!best) return { ...noChange(cleared), state: cleared };
330|  return {
331|    state: { ...cleared, currentId: best.id, currentStartedSec: nowSec },
332|    switchToId: best.id,
333|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
334|  };
335|}
336|
337|// Style change from user action: switches at once with the normal
338|// crossfade, no dwell and no min-track rule, and sets the override like
339|// Next.
340|export function switchStyle(
341|  state: SchedulerState,
342|  signal: SceneSignal | null,
343|  manifest: MusicManifest,
344|  nowSec: number,
345|  style: string,
346|  override?: Partial<MusicConfig>,
347|): ScheduleDecision {
348|  // The reader blocks style changes while a playlist plays. The guard
349|  // keeps the saved index pointing at the current track if one slips by.
350|  if (state.playlist !== null) return noChange(state);
351|  const config = resolveConfig(override ?? MUSIC_CONFIG);
352|  const picked = requestStyleChange(manifest, style, signal, config);
353|  if (!picked) return noChange(state);
354|  return {
355|    state: {
356|      ...state,
357|      currentId: picked.track.id,
358|      currentStartedSec: nowSec,
359|      overrideId: picked.track.id,
360|      overrideSceneId: state.activeSceneId,
361|    },
362|    switchToId: picked.track.id,
363|    crossfadeSec: config.crossfadeSec,
364|  };
365|}
366|
367|export { MUSIC_CONFIG };

